export function parseLockStreamflowV2Instruction<
  TProgram extends string,
  TAccountMetas extends readonly IAccountMeta[],
>(
  instruction: IInstruction<TProgram> &
    IInstructionWithAccounts<TAccountMetas> &
    IInstructionWithData<Uint8Array>
): ParsedLockStreamflowV2Instruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 27) {
    // TODO: Coded error.
    throw new Error('Not enough accounts');
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = instruction.accounts![accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === GENESIS_PROGRAM_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      genesisAccount: getNextAccount(),
      bucket: getNextAccount(),
      baseMint: getNextAccount(),
      quoteMint: getNextAccount(),
      genesisBaseTokenAccount: getNextAccount(),
      bucketQuoteTokenAccount: getNextAccount(),
      recipient: getNextAccount(),
      authority: getNextAccount(),
      sender: getNextAccount(),
      senderTokenAccount: getNextAccount(),
      feeQuoteTokenAccount: getNextAccount(),
      metadata: getNextAccount(),
      escrowTokens: getNextAccount(),
      recipientTokens: getNextAccount(),
      streamflowTreasury: getNextAccount(),
      streamflowTreasuryTokens: getNextAccount(),
      withdrawor: getNextAccount(),
      partner: getNextAccount(),
      partnerTokens: getNextAccount(),
      feeOracle: getNextAccount(),
      rent: getNextAccount(),
      timelockProgram: getNextAccount(),
      baseTokenProgram: getNextAccount(),
      quoteTokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      backendSigner: getNextOptionalAccount(),
    },
    data: getLockStreamflowV2InstructionDataDecoder().decode(instruction.data),
  };
}
